    grid = [[0]*17 for _ in range(14)]

    def is_on_line(p1, p2, p):
        x0, y0 = p1
        x1, y1 = p2
        px, py = p
        return abs((y1 - y0) * (x0 - px) - (x1 - x0) * (y0 - py)) < 0.5

    # Draw edges of hull with value 5
    connections = [
        ((3,6), (8,1)),
        ((8,1), (12,7)),
        ((12,7), (10,10)),
        ((10,10), (8,12)),
        ((8,12), (3,6)),
    ]

    for p1, p2 in connections:
        for x in range(min(p1[1], p2[1]), max(p1[1], p2[1])+1):
            for y in range(min(p1[0], p2[0]), max(p1[0], p2[0])+1):
                if is_on_line(p1, p2, (x, y)):
                    grid[y][x] = 5

    # Also fill interior with value 3
    for r in range(14):
        for c in range(17):
            # Test if point is inside hull
            for i, (p1, p2) in enumerate(connections):
                x0, y0 = p1
                x1, y1 = p2
                px, py = c, r
                cross = (x1 - x0) * (py - y0) - (y1 - y0) * (px - x0)
                if i == 0:
                    sign = cross >= 0
                else:
                    sign = not (i == len(connections)-1 and cross <= 0)
                if not abs(cross) < 0.5:
                    break
            grid[r][c] = 3

